<div class="studio-shell home-container" x-data="{
    failed: false, dirty: false, recoverable: false, backup: null, generation: 0, savingGeneration: null,
    key: 'studio:{{ auth()->id() }}:{{ $recipeId ?? $creationToken }}',
    init() { try { this.backup = JSON.parse(sessionStorage.getItem(this.key)); this.recoverable = !!this.backup; } catch {} },
    changed() { this.dirty = true; this.generation++; this.$nextTick(() => { try { sessionStorage.setItem(this.key, JSON.stringify({ version: this.$wire.editorVersion, data: this.$wire.data })); } catch {} }); },
    async autosave() { if (!this.$wire.recipeId) return; this.changed(); this.savingGeneration = this.generation; try { await this.$wire.autosave(); this.failed = false; } catch { this.failed = true; } },
    recover() { if (this.backup?.version !== this.$wire.editorVersion) { this.failed = true; return; } this.$wire.$set('data', this.backup.data, false); this.recoverable = false; this.dirty = true; },
    saved() { this.failed = false; if (this.savingGeneration !== this.generation) return; this.dirty = false; this.recoverable = false; try { sessionStorage.removeItem(this.key); } catch {} }
}" x-on:studio-saved.window="saved()">
    <header><a class="home-section-link" href="{{ route('recipes.personal', ['locale' => $locale, 'filter' => 'original'], false) }}">{{ __('navigation.my_recipes') }}</a><h1>{{ __('studio.title') }}</h1><p>{{ __('studio.intro') }}</p>@if (!$recipeId)<p>{{ __('studio.autosave_after_create') }}</p>@endif</header>
    <div class="studio-recovery" x-show="recoverable" x-cloak><p>{{ __('studio.recovery') }}</p><button type="button" class="kitchen-button kitchen-button-secondary" x-on:click="recover()">{{ __('studio.recover') }}</button><button type="button" class="kitchen-button kitchen-button-secondary" x-on:click="recoverable = false; sessionStorage.removeItem(key)">{{ __('studio.discard_backup') }}</button></div>
    <p class="field-error" role="alert" x-show="failed" x-cloak>{{ __('studio.network_error') }}</p>
    @if (! $editable)<div class="studio-feedback" role="status">{{ __('studio.frozen') }}@if ($recipe && $recipe->isPubliclyAccessible() && $revisionId === null)<button class="kitchen-button kitchen-button-primary" type="button" wire:click="startRevision" wire:loading.attr="disabled">{{ __('studio.start_revision') }}</button>@endif</div>@endif
    <form wire:submit="save" x-on:submit="savingGeneration = generation" x-on:input="changed()" x-on:change="changed()" x-on:input.debounce.1500ms="autosave()" x-on:change.debounce.1500ms="autosave()">
        <div class="studio-toolbar"><span class="studio-save-status" role="status"><span wire:loading wire:target="save,autosave,submit">{{ __('studio.saving') }}</span><span wire:loading.remove wire:target="save,autosave,submit"><span x-show="dirty" x-cloak>{{ __('studio.dirty') }}</span><span x-show="!dirty">{{ $savedAt ? __('studio.saved', ['time' => $savedAt]) : __('studio.unsaved') }}</span></span><span wire:offline>{{ __('studio.offline') }}</span></span>@if ($editable)<button class="kitchen-button kitchen-button-primary" type="submit" wire:loading.attr="disabled">{{ $recipeId ? __('studio.save') : __('studio.create_draft') }}</button>@if ($recipeId)<button class="kitchen-button kitchen-button-secondary" type="button" wire:click="submit" wire:confirm="{{ __('studio.submit_confirm') }}" wire:loading.attr="disabled">{{ __('studio.submit') }}</button>@endif @endif<a class="kitchen-button kitchen-button-secondary" href="#studio-preview">{{ __('studio.preview') }}</a></div>
        @if ($errors->any())<div class="studio-feedback" role="alert"><p>{{ __('studio.save_errors') }}</p><ul>@foreach ($errors->all() as $message)<li>{{ $message }}</li>@endforeach</ul></div>@endif
        {{ $this->form }}
    </form>
    @if ($recipeId && $editable)<div class="studio-toolbar">{{ $this->uploadImageAction }}{{ $this->videoAction }}{{ $this->removeMediaAction }}{{ $this->suggestDietaryAction }}</div>@endif
    <section id="studio-preview" class="studio-review" aria-labelledby="studio-preview-title"><h2 id="studio-preview-title">{{ __('studio.preview') }}</h2><p>{{ __('studio.preview_saved') }}</p>@include('recipes.partials.studio-preview', ['review' => $review])</section>
    @if ($recipe)<section class="studio-history" aria-labelledby="studio-history-title"><h2 id="studio-history-title">{{ __('studio.history') }}</h2><p>{{ __('studio.state', ['status' => __('kitchen.'.($target instanceof \App\Models\RecipeRevision ? $target->status->value : ($recipe->status === 'pending' ? 'in_review' : $recipe->status)))]) }}</p>@if ($recipe->rejection_reason)<p class="studio-feedback">{{ $recipe->rejection_reason }}</p>@endif<ol>@foreach ($history as $revision)<li wire:key="revision-{{ $revision->id }}"><strong>{{ __('studio.revision_number', ['number' => $revision->revision_number]) }}</strong> · {{ __('kitchen.'.$revision->status->value) }}@if ($revision->rejection_reason)<p>{{ $revision->rejection_reason }}</p>@endif @if ($revision->review_notes)<p>{{ $revision->review_notes }}</p>@endif @if ($revision->status === \App\Enums\RecipeRevisionStatus::Rejected && ! $revisionId && $recipe->isPubliclyAccessible())<button type="button" class="kitchen-button kitchen-button-secondary" wire:click="startRevision({{ $revision->id }})">{{ __('studio.revise_rejected') }}</button>@endif</li>@endforeach</ol>{{ $history->links() }}</section>@endif
